class Solution {
public:
    int maximumProfit(std::vector<int>& present, std::vector<int>& future, int budget) {
        std::vector<int> dp(budget + 1, 0);
        for (int i = 0; i < (int)present.size(); ++i) {
            int p = present[i], profit = future[i] - p;
            if (profit > 0) {
                for (int b = budget; b >= p; --b) {
                    dp[b] = std::max(dp[b], dp[b - p] + profit);
                }
            }
        }
        return dp[budget];
    }
};

class Solution {
    public int maximumProfit(int[] present, int[] future, int budget) {
        int[] dp = new int[budget + 1];
        for (int i = 0; i < present.length; i++) {
            int p = present[i];
            int profit = future[i] - p;
            if (profit > 0) {
                for (int b = budget; b >= p; b--) {
                    dp[b] = Math.max(dp[b], dp[b - p] + profit);
                }
            }
        }
        return dp[budget];
    }
}

var maximumProfit = function(present, future, budget) {
    const dp = new Int32Array(budget + 1);
    for (let i = 0; i < present.length; i++) {
        const p = present[i];
        const profit = future[i] - p;
        if (profit > 0) {
            for (let b = budget; b >= p; b--) {
                if (dp[b - p] + profit > dp[b]) {
                    dp[b] = dp[b - p] + profit;
                }
            }
        }
    }
    return dp[budget];
};
